"use client";

import { useState } from "react";
import { createClient } from "@/lib/supabase/client";

export default function Services() {

  const supabase = createClient();

  const [name, setName] = useState("");
  const [price, setPrice] = useState("");
  const [duration, setDuration] = useState("");
  const [message, setMessage] = useState("");


  async function addService() {

    setMessage("Checking account...");


    // Get logged-in user
    const {
      data: { user },
      error: userError
    } = await supabase.auth.getUser();


    if (userError || !user) {
      setMessage("You are not logged in.");
      return;
    }


    // Find groomer business
    const {
      data: groomers,
      error: groomerError
    } = await supabase
      .from("groomers")
      .select("*")
      .eq("user_id", user.id);


    if (groomerError) {
      setMessage(
        "Database error: " + groomerError.message
      );
      return;
    }


    if (!groomers || groomers.length === 0) {
      setMessage(
        "No business found. Go to onboarding first."
      );
      return;
    }


    const groomer = groomers[0];


    // Add service
    const {
      error: serviceError
    } = await supabase
      .from("services")
      .insert({
        groomer_id: groomer.id,
        name: name,
        duration_minutes: Number(duration),
        price_cents: Number(price) * 100
      });


    if (serviceError) {
      setMessage(
        "Service error: " + serviceError.message
      );
      return;
    }


    setMessage("✅ Service added!");

    setName("");
    setPrice("");
    setDuration("");

  }



  return (

    <main className="min-h-screen bg-green-50 flex items-center justify-center p-6">

      <div className="bg-white rounded-3xl shadow-lg p-8 w-full max-w-md">


        <h1 className="text-3xl font-bold mb-6">
          ✂️ Add Grooming Service
        </h1>


        <input
          className="border p-3 rounded-xl w-full mb-3"
          placeholder="Service name"
          value={name}
          onChange={(e)=>setName(e.target.value)}
        />


        <input
          className="border p-3 rounded-xl w-full mb-3"
          placeholder="Price (example 50)"
          type="number"
          value={price}
          onChange={(e)=>setPrice(e.target.value)}
        />


        <input
          className="border p-3 rounded-xl w-full mb-5"
          placeholder="Duration in minutes"
          type="number"
          value={duration}
          onChange={(e)=>setDuration(e.target.value)}
        />


        <button
          onClick={addService}
          className="bg-green-600 hover:bg-green-700 text-white w-full py-3 rounded-xl"
        >
          Add Service
        </button>


        {message && (
          <p className="mt-4 text-center text-gray-700">
            {message}
          </p>
        )}


      </div>

    </main>

  );
}